import {Trace} from './trace.mjs';
function square(variant){const patterns=[['o','o','o','o','-','|'],['/','\\','\\','/','*','*'],['A','A','C','C','B','B'],['A','C','A','C','B','B'],['A','C','C','A','B','B']],chars=patterns[variant],lit=c=>c==='\\'?"'\\\\'":`'${c}'`,source=`#include <stdio.h>\nint main(void)\n{\n    int x = 3;\n    int y = 3;\n    int row = 0;\n    int col;\n    char c;\n    while (row < y)\n    {\n        col = 0;\n        while (col < x)\n        {\n            if (row == 0 && col == 0)\n                c = ${lit(chars[0])};\n            else if (row == 0 && col == x - 1)\n                c = ${lit(chars[1])};\n            else if (row == y - 1 && col == 0)\n                c = ${lit(chars[2])};\n            else if (row == y - 1 && col == x - 1)\n                c = ${lit(chars[3])};\n            else if (row == 0 || row == y - 1)\n                c = ${lit(chars[4])};\n            else if (col == 0 || col == x - 1)\n                c = ${lit(chars[5])};\n            else\n                c = ' ';\n            putchar(c);\n            col++;\n        }\n        putchar('\\n');\n        row++;\n    }\n    return (0);\n}`;const b=new Trace('square-'+variant,`Rush 0${variant} · rows, columns, and borders`,'Nested loops choose a character from its row/column position and then print it.',source);for(const [id,v,loc]of [['x',3,0x2000],['y',3,0x2004],['row',0,0x2008]])b.step(`int ${id} = ${v};`,'Initialize '+id,`Store ${v} in ${id}.`,'This 3×3 example includes four corners, edges, and one interior cell.','value → '+id,()=>b.cell(id,id,'int',loc,v));b.step('int col;','Create the column counter','Reserve col without initialization.','It is initialized at the start of each row.','col created',()=>b.cell('col','col','int',0x200C,undefined));b.step('char c;','Create the output char','Reserve c without initialization.','Each position’s branch writes c before it is printed.','c created',()=>b.cell('c','c','char',0x2010,undefined));for(let r=0;r<3;r++){b.step('while (row < y)','Check for another row',`${r} < 3 is true.`,'The outer loop controls vertical progress.','true → row',()=>{},['row','y']);b.step('col = 0;','Start at the left edge','Set col to zero.','Every row begins at column zero.','0 → col',()=>b.set('col',0));for(let c=0;c<3;c++){b.step('while (col < x)','Check for another column',`${c} < 3 is true.`,'The inner loop controls horizontal progress.','true → position',()=>{},['col','x']);const tests=[['if (row == 0 && col == 0)',r===0&&c===0],['else if (row == 0 && col == x - 1)',r===0&&c===2],['else if (row == y - 1 && col == 0)',r===2&&c===0],['else if (row == y - 1 && col == x - 1)',r===2&&c===2],['else if (row == 0 || row == y - 1)',r===0||r===2],['else if (col == 0 || col == x - 1)',c===0||c===2]];let which=6;for(let t=0;t<tests.length;t++){b.step(tests[t][0],'Classify the position',`At row ${r}, col ${c}, this test is ${tests[t][1]}.`,'Corner tests precede edge tests so the corner’s character wins.','position test → '+tests[t][1],()=>{},['row','col','x','y']);if(tests[t][1]){which=t;break;}}if(which===6)b.step('else','Select the interior','No border condition matched.','Interior positions print a space.','no border → space');const ch=which===6?' ':chars[which],line=b.code.findIndex((l,i)=>l.trim()===`c = ${lit(ch)};`&&i>(which===6?24:12))+1;const assignmentIndices=b.code.flatMap((l,i)=>l.trim().startsWith('c = ')?[i+1]:[]);b.step(assignmentIndices[which],'Choose the char',`Store ${JSON.stringify(ch)} in c for this position.`,'The char cell changes only if the new char differs from its old value.','selected border char → c',()=>b.set('c',ch));b.step('putchar(c);','Print this position','Append the selected char.','The output builds one row from left to right.','c → terminal',()=>{b.state.output+=ch;b.state.world={kind:'board',rows:b.state.output.split('\n').filter(Boolean).map(s=>s.split('')),current:[r,c]};},['c']);b.step('col++;','Move right',`Increase col to ${c+1}.`,'No output changes in this counter update.','col + 1 → col',()=>b.set('col',c+1));}b.step('while (col < x)','Finish the row','3 < 3 is false.','All three positions were printed.','false → newline',()=>{},['col','x']);b.step("putchar('\\n');",'End the output row','Print one newline.','The next character starts the next terminal line.','newline → terminal',()=>b.state.output+='\n');b.step('row++;','Move down',`Increase row to ${r+1}.`,'The next row resets col to zero.','row + 1 → row',()=>b.set('row',r+1));}b.step('while (row < y)','Finish the rectangle','3 < 3 is false.','The complete 3×3 variant is printed. See the requirements for width/height edge cases.','false → stop',()=>{},['row','y']);return b.finish('return (0);','');}
function visible(){const b=new Trace('visibility','Sky Scraper · count visible heights','A box is visible from the left only if it exceeds every height seen before it.',`#include <stdio.h>\nint main(void)\n{\n    int row[4] = {2, 1, 3, 4};\n    int highest = 0;\n    int seen = 0;\n    int i = 0;\n    while (i < 4)\n    {\n        if (row[i] > highest)\n        {\n            highest = row[i];\n            seen++;\n        }\n        i++;\n    }\n    printf("visible=%d\\n", seen);\n    return (0);\n}`);b.step('int row[4] = {2, 1, 3, 4};','Create four heights','Initialize 2, 1, 3, 4 in a single row.','This row contains every required height exactly once.','heights → row',()=>{b.ints('h',[2,1,3,4],0x1000,'row');b.state.world={kind:'board',rows:[[2,1,3,4]],current:null};});for(const [id,loc]of [['highest',0x2000],['seen',0x2004],['i',0x2008]])b.step(`int ${id} = 0;`,'Initialize '+id,'Start at zero.','highest tracks the running maximum; seen counts visible boxes.','0 → '+id,()=>b.cell(id,id,'int',loc,0));let max=0,seen=0;for(let i=0;i<4;i++){const h=[2,1,3,4][i];b.step('while (i < 4)','Check the row boundary',`${i} < 4 is true.`,'Each height is examined once.','true → body',()=>{b.state.world.current=[0,i];},['i']);const test=h>max;b.step('if (row[i] > highest)','Check whether this box is visible',`${h} > ${max} is ${test}.`,test?'This box is taller than every previous box, so it is visible.':'A previous taller box hides this box from the left.','height > running maximum → '+test,()=>{},['h'+i,'highest'],['h'+i]);if(test){max=h;seen++;b.step('highest = row[i];','Update the highest seen','Store '+h+' as the running maximum.','Later smaller boxes will be hidden.','current height → highest',()=>b.set('highest',h),['h'+i]);b.step('seen++;','Count the visible box','Increase seen to '+seen+'.','A new record height adds exactly one visible box.','seen + 1 → seen',()=>b.set('seen',seen));}b.step('i++;','Move right','Set i to '+(i+1)+'.','A reverse-direction scan applies the same rule from the other end.','i + 1 → i',()=>b.set('i',i+1));}b.step('while (i < 4)','Finish the scan','4 < 4 is false.','Heights 2, 3, and 4 are visible from the left; height 1 is hidden.','false → stop',()=>{},['i']);return b.finish('printf("visible=%d\\n", seen);','visible=3\n');}
function backtrack(){const code=`#include <stdio.h>\nint board[2][2];\nint solve(int cell)\n{\n    int row;\n    int col;\n    int value;\n    if (cell == 4)\n        return (board[0][0] == 2);\n    row = cell / 2;\n    col = cell % 2;\n    value = 1;\n    while (value <= 2)\n    {\n        if (board[row][1 - col] != value && board[1 - row][col] != value)\n        {\n            board[row][col] = value;\n            if (solve(cell + 1))\n                return (1);\n            board[row][col] = 0;\n        }\n        value++;\n    }\n    return (0);\n}\nint main(void)\n{\n    if (solve(0))\n        printf("%d %d\\n%d %d\\n", board[0][0], board[0][1], board[1][0], board[1][1]);\n    return (0);\n}`;const b=new Trace('backtracking','Backtracking · try, reject, and undo','A miniature 2×2 constraint problem shows the search mechanism used in the 4×4 Rush.',code);b.state.world={kind:'board',rows:[[0,0],[0,0]],current:null};b.ints('b',[0,0,0,0],0x1000,'board','static storage');for(let i=0;i<4;i++)b.state.cells['b'+i].name=`board[${Math.floor(i/2)}][${i%2}]`;b.steps[0]={...b.steps[0],cells:structuredClone(b.state.cells),world:structuredClone(b.state.world),what:'Static board storage starts zero-initialized. This teaching puzzle uses heights 1–2, row/column uniqueness, and an extra rule that the top-left value must be 2. It demonstrates search, not the full 4×4 Rush contract.'};let serial=0;b.step('if (solve(0))','Start the search','Pass cell index 0 into solve.','main waits for either success or exhaustion.','0 → solve parameter');function visit(cell){const k=serial++,scope='solve('+cell+') #'+k,loc=0x3000+k*32;b.enter(scope);b.cell('cell'+k,'cell','int',loc,cell);b.capture(b.code.findIndex(l=>l==='int solve(int cell)')+1,'Enter solve('+cell+')',`This call gets its own cell parameter with value ${cell}.`,'Earlier calls pause while this call tries a later cell.','cell argument → local parameter');for(const [id,offset]of [['row',4],['col',8],['value',12]])b.step('int '+id+';','Create local '+id,'Reserve the automatic local object.','Each recursive call has its own counters.','local storage created',()=>b.cell(id+k,id,'int',loc+offset,undefined));b.step('if (cell == 4)','Check if all cells are filled',`${cell} == 4 is ${cell===4}.`,'A full board is checked against the final extra constraint.','cell count → completion test',()=>{},['cell'+k]);if(cell===4){const success=b.state.cells.b0.value===2;b.step('return (board[0][0] == 2);','Check the final constraint',`Top-left ${b.state.cells.b0.value} == 2 is ${success}.`,'A false result makes the caller undo its last trial.','constraint result → caller',()=>{},['b0']);b.leave();return success;}const r=Math.floor(cell/2),c=cell%2;for(const [id,at,v]of [['row','row = cell / 2;',r],['col','col = cell % 2;',c],['value','value = 1;',1]])b.step(at,'Initialize '+id,`Store ${v} in ${id}.`,'Division and remainder map the linear cell index to coordinates.','computed value → local',()=>b.set(id+k,v),['cell'+k]);for(let v=1;v<=2;v++){b.step('while (value <= 2)','Check a candidate',`${v} <= 2 is true.`,'Candidates are tried in increasing order.','true → candidate',()=>{b.state.world.current=[r,c];},['value'+k]);const otherRow=r*2+1-c,otherCol=(1-r)*2+c,safe=b.state.cells['b'+otherRow].value!==v&&b.state.cells['b'+otherCol].value!==v;b.step('if (board[row][1 - col] != value && board[1 - row][col] != value)','Check row and column duplicates',`Candidate ${v} is ${safe?'absent from':'already present in'} the other row/column positions.`,'A rejected candidate is never written to the board.','duplicate checks → '+safe,()=>{},['b'+otherRow,'b'+otherCol,'value'+k],['b'+cell]);if(safe){b.step('board[row][col] = value;','Place the trial value',`Write ${v} into board[${r}][${c}].`,'A trial placement is provisional until deeper calls succeed.','candidate → board cell',()=>{b.set('b'+cell,v);b.state.world.rows[r][c]=v;},['value'+k],['b'+cell]);b.step('if (solve(cell + 1))','Explore the next cell','Pass '+(cell+1)+' into a recursive call.','This call pauses and preserves its current candidate.','next cell → child');const ok=visit(cell+1);b.step('if (solve(cell + 1))','Receive the child result','The deeper search returns '+ok+'.',ok?'Keep this placement and return success.':'No complete solution used this placement; undo it before trying another candidate.','child result → branch');if(ok){b.step('return (1);','Keep the successful branch','Return true without clearing this cell.','Successful placements survive all the way back to main.','1 → caller');b.leave();return true;}b.step('board[row][col] = 0;','Undo the unsuccessful trial','Reset this cell to zero.','Backtracking restores the earlier state before exploring another branch.','0 → trial cell',()=>{b.set('b'+cell,0);b.state.world.rows[r][c]=0;},[],['b'+cell]);}b.step('value++;','Try the next candidate','Increase value to '+(v+1)+'.','The loop condition decides whether another candidate exists.','value + 1 → value',()=>b.set('value'+k,v+1));}b.step('while (value <= 2)','Exhaust the candidates','3 <= 2 is false.','Return failure to the caller, which may undo its own placement.','false → failure',()=>{},['value'+k]);b.step('return (0);','Report branch failure','No candidate led to a solution at this cell.','This return is from solve, not from main.','0 → caller');b.leave();return false;}visit(0);b.step('if (solve(0))','Receive a solution in main','The outer call returns true.','All solve frames have returned; the successful board remains.','success → main');return b.finish('printf("%d %d\\n%d %d\\n", board[0][0], board[0][1], board[1][0], board[1][1]);','2 1\n1 2\n');}
function rosetta(){const code=`#include <stdio.h>\nint main(void)\n{\n    int number = 42;\n    int tens = number / 10 * 10;\n    int units = number % 10;\n    const char *tens_word = NULL;\n    const char *units_word = NULL;\n    if (tens == 40)\n        tens_word = "forty";\n    if (units == 2)\n        units_word = "two";\n    if (tens_word != NULL && units_word != NULL)\n        printf("%s %s\\n", tens_word, units_word);\n    return (0);\n}`;const b=new Trace('dictionary','Rosetta Stone · decompose and look up','Separate a number into dictionary keys, then use dictionary values for the output.',code);b.step('int number = 42;','Create the numeric example','Store 42.','This small example isolates decomposition and lookup. The full project must parse the external dictionary, accept larger numbers, and handle errors.','42 → number',()=>{b.cell('number','number','int',0x2000,42);b.chars('forty','forty',0x1000,'dictionary[40]','dictionary');b.chars('two','two',0x1100,'dictionary[2]','dictionary');});b.step('int tens = number / 10 * 10;','Find the tens key','42 / 10 * 10 yields 40.','Dictionary key 40 supplies the tens word.','40 → tens',()=>b.cell('tens','tens','int',0x2004,40),['number']);b.step('int units = number % 10;','Find the units key','42 % 10 yields 2.','The source requires combining initial keys such as 40 and 2 rather than relying on a special entry for 42.','2 → units',()=>b.cell('units','units','int',0x2008,2),['number']);for(const [id,loc]of [['tens_word',0x2010],['units_word',0x2018]])b.step(`const char *${id} = NULL;`,'Initialize an unresolved word','Set the word pointer to NULL.','Do not print an unresolved word pointer.','NULL → word pointer',()=>b.cell(id,id,'const char *',loc,'NULL'));for(const [key,n,id,target,loc,word]of [['tens',40,'tens_word','forty0',0x2010,'forty'],['units',2,'units_word','two0',0x2018,'two']]){b.step(`if (${key} == ${n})`,'Match a dictionary key',`${key} equals ${n}.`,'The full project searches parsed entries. These two if branches stand in for a miniature two-entry dictionary.','numeric key → entry',()=>{},[key]);b.step(`${id} = "${word}";`,'Select the dictionary value','Copy the word’s first-char address into '+id+'.','The output uses a stored word value; it is not generated letter by letter from the number.','dictionary word address → pointer',()=>b.ptr(id,id,'const char *',loc,target));}b.step('if (tens_word != NULL && units_word != NULL)','Check both resolutions','Both required word addresses are present.','The full assignment reports Dict Error when a number cannot be resolved.','resolved words → output',()=>{},['tens_word','units_word']);return b.finish('printf("%s %s\\n", tens_word, units_word);','forty two\n');}
export function buildRushSimulations(){return [...Array.from({length:5},(_,i)=>square(i)),visible(),backtrack(),rosetta()];}
